from itertools import product

def brute_cycle(n, m):
    # people 1..n in a circle; adjacency edges (i, i+1) and (n, 1); n=2 degenerates to one edge pair {1,2}
    edges = [(i, i+1) for i in range(1, n)] + ([(n, 1)] if n > 2 else [])
    cnt = 0
    for assign in product(range(m), repeat=n):
        if all(assign[u-1] != assign[v-1] for u, v in edges):
            cnt += 1
    return cnt

def formula(n, m):
    return (m-1)**n + (m-1 if n % 2 == 0 else -(m-1))

ok = True
for n in range(2, 9):
    for m in range(2, 6):
        b, f = brute_cycle(n, m), formula(n, m)
        if b != f:
            ok = False
            print(f'MISMATCH n={n} m={m}: brute={b} formula={f}')
print('formula vs brute force over n=2..8, m=2..5:', 'ALL MATCH' if ok else 'FAILED')
